# Generated by build.py from recipe.yml for recipe tftp-choose-a-block-size. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site logs
head -c 3000 /dev/urandom > site/big.bin
surl -v --log-file logs/surl.log --directory site tftp://127.0.0.1:8080/ &
sleep 1
curl -v --tftp-blksize 1024 -o copy.bin tftp://127.0.0.1:8080/big.bin 2>&1 | grep -E "blksize|tsize"
kill $(jobs -p)
